function validateGenericApiSymbol(actual, expected) {
  if (expected.startsWith("#")) {
    assert.deepEqual(actual, {
      kind: "ordinal",
      ordinal: Number.parseInt(expected.slice(1), 10),
    });
  } else {
    assert.deepEqual(actual, { kind: "name", name: expected });
  }
}

