            byteDelivery: "bounded-host-range-read",
            looseFileProbe: archiveSourceLooseProbeCall,
            archiveOpens: archiveSourceOpenCalls,
            archiveReads: archiveSourceReads,
            immutableSourceWriteDenied: true,
